function mtlRgbToHex(parts){
  const nums=parts.map(v=>Math.max(0,Math.min(255,Math.round(parseFloat(v)*255))));
  return '#'+nums.map(v=>v.toString(16).padStart(2,'0')).join('');
}
function parseSimpleMtl(txt=''){
  const mats={}; let cur=null;
  for(const raw of String(txt).split('\n')){
    const line=raw.trim(); if(!line||line.startsWith('#')) continue;
    const parts=line.split(/\s+/); const cmd=parts.shift();
    if(cmd==='newmtl'){ cur={name:parts.join(' '),color:'#b8b0a2',alpha:1,emissive:false}; mats[cur.name]=cur; }
    else if(cmd==='Kd'&&cur) cur.color=mtlRgbToHex(parts);
    else if(cmd==='d'&&cur) cur.alpha=Math.max(.1,Math.min(1,parseFloat(parts[0]||'1')));
    else if(cmd==='Ke'&&cur) cur.emissive=parts.some(v=>parseFloat(v)>0.01);
  }
  return mats;
}
function buildEmbeddedObj(scene,name,objText,mtlText,opt={}){
  if(!objText) return null;
  const mats=parseSimpleMtl(mtlText||'');
  const verts=[null]; const groups={}; let current='Default';
  function grp(n){ if(!groups[n]) groups[n]={positions:[],indices:[]}; return groups[n]; }
  for(const raw of String(objText).split('\n')){
    const line=raw.trim(); if(!line||line.startsWith('#')) continue;
    if(line.startsWith('v ')){
      const p=line.split(/\s+/); verts.push([parseFloat(p[1]),parseFloat(p[2]),parseFloat(p[3])]);
    }else if(line.startsWith('usemtl ')) current=line.slice(7).trim()||'Default';
    else if(line.startsWith('f ')){
      const refs=line.slice(2).trim().split(/\s+/).map(tok=>{
        let idx=parseInt(tok.split('/')[0],10); if(Number.isNaN(idx)) return null; if(idx<0) idx=verts.length+idx; return idx;
      }).filter(Boolean);
      if(refs.length<3) continue;
      const g=grp(current);
      for(let i=1;i<refs.length-1;i++){
        const tri=[refs[0],refs[i],refs[i+1]];
        for(const id of tri){ const v=verts[id]; if(!v) continue; g.positions.push(v[0],v[1],v[2]); g.indices.push(g.indices.length); }
      }
    }
  }
  const root=new B.TransformNode(name,scene); root.rotationQuaternion=null;
  for(const [matName,data] of Object.entries(groups)){
    if(!data.positions.length) continue;
    const mesh=new B.Mesh(name+'_'+matName.replace(/[^a-z0-9_\-]/gi,'_'),scene);
    const vd=new B.VertexData(); vd.positions=data.positions; vd.indices=data.indices; const normals=[]; B.VertexData.ComputeNormals(vd.positions,vd.indices,normals); vd.normals=normals; vd.applyToMesh(mesh,false);
    const md=mats[matName]||{color:'#c8b8a2',alpha:1};
    const material=new B.PBRMaterial(mesh.name+'_mat',scene); material.albedoColor=B.Color3.FromHexString(md.color||'#c8b8a2'); material.roughness=.88; material.metallic=.03; material.alpha=md.alpha??1;
    const low=(matName||'').toLowerCase();
    if(low.includes('glass')){ material.alpha=.35; material.metallic=.1; material.roughness=.08; }
    if(low.includes('light')){ material.emissiveColor=B.Color3.FromHexString(md.color||'#eee4b8').scale(.65); material.roughness=.25; }
    if(low.includes('grey')||low.includes('metal')){ material.metallic=.18; material.roughness=.48; }
    mesh.material=material; mesh.parent=root; mesh.receiveShadows=true;
  }
  if(opt.scale) root.scaling.copyFrom(opt.scale);
  if(opt.rotation) root.rotation.copyFrom(opt.rotation);
  if(opt.position) root.position.copyFrom(opt.position);
  if(opt.pickable===false) for(const ch of root.getChildMeshes()) ch.isPickable=false;
  if(opt.freeze) for(const ch of root.getChildMeshes()) ch.freezeWorldMatrix();
  return root;
}
function lobbyAsset(scene,objName,mtlName,opt={}){
  const root=buildEmbeddedObj(scene,opt.name||objName,LOBBY_ASSETS[objName],LOBBY_ASSETS[mtlName],opt);
  if(root) G.lobbyMeshes.push(root);
  return root;
}
function hubCameraSpawn(scene){
  const cam=G.xr?.baseExperience?.camera||scene.activeCamera; if(!cam) return;
  cam.position.x=0; cam.position.z=-2.65; if(G.desktop) cam.position.y=1.68;
  try{ if(cam.rotation){ cam.rotation.x=0; cam.rotation.y=0; cam.rotation.z=0; } }catch{}
}

const AudioCtor=window.AudioContext||window.webkitAudioContext;
const audio=AudioCtor?new AudioCtor():null;
function tone(freq=220,dur=.08,type='sine',gain=.05,slide=0){
  if(!audio)return; if(audio.state==='suspended') audio.resume().catch(()=>{});
  const o=audio.createOscillator(), g=audio.createGain(); o.type=type; o.frequency.setValueAtTime(freq,audio.currentTime); if(slide) o.frequency.exponentialRampToValueAtTime(Math.max(30,freq+slide),audio.currentTime+dur);
  g.gain.setValueAtTime(gain,audio.currentTime); g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+dur); o.connect(g).connect(audio.destination); o.start(); o.stop(audio.currentTime+dur);
}
function impactSound(material='wood',power=1){ const m={metal:[180,'square'],glass:[620,'triangle'],ceramic:[420,'triangle'],plastic:[260,'square'],wood:[140,'sine'],paper:[360,'triangle']}[material]||[170,'sine']; tone(m[0]*(1+Math.random()*.12),.05+.04*power,m[1],.025+.035*power,-m[0]*.3); }

function stopLobbyAudio(){
  if(!G.lobbyAudio)return;
  try{G.lobbyAudio.nodes?.forEach(n=>{try{n.stop?.()}catch{} try{n.disconnect?.()}catch{}});}catch{}
  G.lobbyAudio=null;
}
function startLobbyAudio(){
  if(!audio||G.meta.settings?.music===false||G.lobbyAudio)return;
  if(audio.state==='suspended') audio.resume().catch(()=>{});
  try{
    const master=audio.createGain(); master.gain.value=.055; master.connect(audio.destination);
    // soft cozy room hum
    const hum=audio.createOscillator(); hum.type='sine'; hum.frequency.value=58;
    const humGain=audio.createGain(); humGain.gain.value=.018; hum.connect(humGain).connect(master); hum.start();
    // very quiet higher harmonic
    const hum2=audio.createOscillator(); hum2.type='sine'; hum2.frequency.value=116;
    const hum2Gain=audio.createGain(); hum2Gain.gain.value=.005; hum2.connect(hum2Gain).connect(master); hum2.start();

    // synthetic fireplace crackle: sparse filtered noise bursts
    const crackleGain=audio.createGain(); crackleGain.gain.value=.13; crackleGain.connect(master);
    let cancelled=false;
    const nodes=[hum,hum2,master,humGain,hum2Gain,crackleGain];
    function crack(){
      if(cancelled||G.state!=='hub'||G.meta.settings?.music===false)return;
      const dur=.035+Math.random()*.08;
      const buf=audio.createBuffer(1,Math.ceil(audio.sampleRate*dur),audio.sampleRate);
      const d=buf.getChannelData(0);
      for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*(1-i/d.length);
      const src=audio.createBufferSource(); src.buffer=buf;
      const filt=audio.createBiquadFilter(); filt.type='bandpass'; filt.frequency.value=700+Math.random()*1800; filt.Q.value=.6;
      const g=audio.createGain(); g.gain.value=.10+Math.random()*.22;
      src.connect(filt).connect(g).connect(crackleGain); src.start();
      setTimeout(()=>{try{src.disconnect();filt.disconnect();g.disconnect();}catch{}},(dur+0.1)*1000);
      if(!cancelled) setTimeout(crack,120+Math.random()*520);
    }
    crack();
    G.lobbyAudio={nodes,stop:()=>{cancelled=true;}};
  }catch(e){console.warn('Lobby ambience unavailable',e);}
}

function npcVoice(kind='hit'){const base=kind==='ko'?115:kind==='throw'?230:kind==='boss'?82:165;const type=kind==='boss'?'sawtooth':'triangle';tone(base+Math.random()*35,kind==='ko'?.12:.055,type,kind==='boss'?.03:.016,kind==='ko'?-45:70);}
function bodyHitSound(power=1){const p=Math.max(.35,Math.min(1.25,power));tone(82+Math.random()*10,.08,'sine',.05*p,-30);setTimeout(()=>tone(190+Math.random()*30,.045,'square',.03*p,-80),8);setTimeout(()=>tone(540+Math.random()*70,.025,'triangle',.018*p,-220),15);setTimeout(()=>tone(72+Math.random()*8,.055,'sine',.035*p,-22),20);}
function spawnHitFX(scene,pos,power=1){try{const m=B.MeshBuilder.CreateSphere('hitFlash',{diameter:.09+Math.min(.1,power*.04),segments:8},scene);m.position.copyFrom(pos);const mm=new B.StandardMaterial('hitFlashMat',scene);mm.diffuseColor=new B.Color3(1,.72,.2);mm.emissiveColor=new B.Color3(1,.34,.05);mm.disableLighting=true;m.material=mm;const st=performance.now();const obs=scene.onBeforeRenderObservable.add(()=>{const t=(performance.now()-st)/110;m.scaling.setAll(1+t*3);mm.alpha=Math.max(0,1-t);if(t>=1){scene.onBeforeRenderObservable.remove(obs);m.dispose(false,true);}});}catch{}}
function musicPulse(){
  if(G.state!=='shift'||G.meta.settings?.music===false)return; const band=G.boss?'boss':G.chaos>72?'mayhem':G.chaos>35?'tension':'shift';
  if(band!==G.lastMusicBand){G.lastMusicBand=band; tone(band==='boss'?52:band==='mayhem'?78:band==='tension'?98:118,.16,'sine',.012,band==='boss'?18:35);}
  const f=band==='boss'?58:band==='mayhem'?82:band==='tension'?110:132; tone(f,.055,'sine',band==='shift'?.006:.009,0);
}
function announce(text,kind='info'){ toast(text,kind==='boss'?2100:1200); if(kind==='good')tone(330,.12,'triangle',.035,150); else if(kind==='danger')tone(105,.1,'square',.04,-40); }
function haptic(ctrl,power=.4,dur=35){ if(G.meta.settings?.haptics===false)return; try{ctrl?.inputSource?.gamepad?.hapticActuators?.[0]?.pulse(Math.min(1,power),dur);}catch{} }

function mat(scene,name,color,rough=.7){ const m=new B.PBRMaterial(name,scene); m.albedoColor=B.Color3.FromHexString(color); m.roughness=rough; m.metallic=rough<.4?.45:.05; return m; }
function box(scene,name,pos,scale,color,parent=null){ const x=B.MeshBuilder.CreateBox(name,{size:1},scene); x.position.copyFrom(pos); x.scaling.copyFrom(scale); x.material=mat(scene,name+'Mat',color); if(parent)x.parent=parent; return x; }
function patternMaterial(scene,name,base,accent='#ffffff',kind='grid'){
  const tex=new B.DynamicTexture(name+'Tex',{width:512,height:512},scene,true);const c=tex.getContext();c.fillStyle=base;c.fillRect(0,0,512,512);c.strokeStyle=accent+'55';c.lineWidth=5;
  if(kind==='wood'){for(let y=0;y<512;y+=64){c.beginPath();c.moveTo(0,y);c.lineTo(512,y);c.stroke();for(let x=(y/64%2)*48;x<512;x+=128){c.beginPath();c.moveTo(x,y);c.lineTo(x,y+64);c.stroke();}}}
  else if(kind==='tile'){for(let x=0;x<512;x+=64){c.beginPath();c.moveTo(x,0);c.lineTo(x,512);c.stroke();}for(let y=0;y<512;y+=64){c.beginPath();c.moveTo(0,y);c.lineTo(512,y);c.stroke();}}
  else if(kind==='concrete'){for(let i=0;i<300;i++){c.fillStyle=i%3?accent+'22':accent+'14';c.fillRect(Math.random()*512,Math.random()*512,2+Math.random()*5,2+Math.random()*5);}}
  else {for(let x=0;x<512;x+=96){c.beginPath();c.moveTo(x,0);c.lineTo(x,512);c.stroke();}for(let y=0;y<512;y+=96){c.beginPath();c.moveTo(0,y);c.lineTo(512,y);c.stroke();}}
  tex.update();tex.uScale=4;tex.vScale=4;const m=new B.PBRMaterial(name,scene);m.albedoTexture=tex;m.roughness=.78;m.metallic=.04;return m;
}
function capsule(scene,name,pos,height,radius,color,parent=null){let x;if(B.MeshBuilder.CreateCapsule)x=B.MeshBuilder.CreateCapsule(name,{height,radius,tessellation:12,subdivisions:4},scene);else{x=B.MeshBuilder.CreateSphere(name,{diameter:radius*2,segments:10},scene);x.scaling.y=Math.max(1,height/(radius*2));}x.position.copyFrom(pos);x.material=mat(scene,name+'Mat',color);if(parent)x.parent=parent;return x;}
function label(scene,text,pos,size=1.1,color='#ffffff'){
  const raw=String(text).split('\n').slice(0,3), lines=[];
  for(const part of raw){ if(part.length<=24){lines.push(part);continue;} const words=part.split(' ');let line='';for(const w of words){const n=(line+' '+w).trim();if(n.length>24&&line){lines.push(line);line=w;}else line=n;}if(line)lines.push(line); }
  const shown=lines.slice(0,3), maxLen=Math.max(4,...shown.map(x=>x.length));
  const width=Math.min(4.2,Math.max(1.0,maxLen*.12))*size, height=(.42+.24*(shown.length-1))*size;
  const p=B.MeshBuilder.CreatePlane('label',{width,height},scene);p.position.copyFrom(pos);p.billboardMode=B.Mesh.BILLBOARDMODE_ALL;
  const tex=new B.DynamicTexture('labelTex',{width:1024,height:384},scene,true);tex.hasAlpha=true;const ctx=tex.getContext();ctx.clearRect(0,0,1024,384);ctx.textAlign='center';ctx.textBaseline='middle';
  const font=Math.max(46,Math.min(92,900/(maxLen+2)));ctx.font=`bold ${font}px Arial`;ctx.fillStyle=color;const gap=118,sy=192-(shown.length-1)*gap/2;shown.forEach((ln,i)=>ctx.fillText(ln,512,sy+i*gap));tex.update();
  const m=new B.StandardMaterial('labelMat',scene);m.diffuseTexture=tex;m.emissiveTexture=tex;m.opacityTexture=tex;m.disableLighting=true;p.material=m;return p;
}
function toast(s,ms=1200){ ui.toast.textContent=s; ui.toast.classList.add('show'); clearTimeout(toast.t); toast.t=setTimeout(()=>ui.toast.classList.remove('show'),ms); }

function saveMeta(){ try{localStorage.setItem('crazyOfficeNightShiftMeta',JSON.stringify(G.meta));}catch(e){console.warn('Meta save failed.',e);} }
function careerTier(){ return Math.min(5,Math.floor(Math.max(0,(G.meta.level||1)-1)/2)); }
function salaryTier(){ const c=G.meta.coins||0; return c>=3000?'EXECUTIVE':c>=1500?'MIDNIGHT':c>=600?'CHROME':'STANDARD'; }
function batColor(){ return selectedBatDef().color; }

